.home-hero {
  @include position(relative);
  @include size(100%, auto);

  .line--1 {
    @include position(absolute, 300px -20px null null);
    @include size(160px, 1px);
    transform: rotate(-45deg);

    .line-anim {
      transition-delay: .5s;
    }
  }

  .line--2 {
    @include position(absolute, 50% null null -265px);
    @include size(680px, 1px);
    transform: rotate(45deg) translateY(-50%) translateY(60px);

    @include mq($until: 'l') {
      display: none;
    }

    @include mq($from: 'l', $until: 'xl') {
      transform: rotate(45deg) translateY(-50%) translateY(220px);
    }

    .line-anim {
      transition-delay: .6s;
    }
  }

  .center {
    @include position(relative);
    @include padding(200px null null);
    z-index: 2;

    // MQ
    @include mq($from: 'm') {
      display: flex;
      flex-direction: column;
      flex-wrap: wrap;
      justify-content: space-between;
    }

    @include mq($until: 'm') {
      padding-top: 115px;
    }
  }

  &-title {
    @include font('serif', 'bold');
    fill: $color-white;
    color: $color-white;
    font-size: rem(120px);
    letter-spacing: ls(-40px);
    line-height: (107 / 120);

    .fx-word:first-of-type {
      letter-spacing: -14px;

      @include mq($from: 'l') {
        @include position(relative, 6px null null null);
        margin-right: 15px;
        letter-spacing: -23px;
      }
    }

    .fx-word:nth-of-type(2) {
      letter-spacing: -4px;

      @include mq($from: 'l') {
        letter-spacing: -8px;
      }
    }

    .fx-word:last-of-type {
      letter-spacing: -4px;

      @include mq($from: 'l') {
        letter-spacing: -6px;
      }
    }

    .fx-letter--6 {
      margin-left: -3px;
    }

    .fx-letter--11 {
      margin-right: -1px;

      @include mq($from: 'l') {
        margin-right: -2px;
      }
    }

    // MQ
    @include mq($from: 'xl') {
      @include size(269px, 404px);
      @include margin(null null null 22.4%);
      text-align: right;
    }

    @include mq($until: 'l') {
      font-size: rem(80px);
    }

    img {
      display: block;
      width: 100%;
    }
  }

  &-content {
    @include size(345px, auto);
    @include margin(145px 60px null auto);
    @include font('alternative', 'regular');
    color: $text-light;
    font-size: rem(14px);
    line-height: (24 / 14);

    // MQ
    @include mq($until: 'xl') {
      width: 50%;
      margin-top: 40px;
      margin-right: 0;
    }

    @include mq($until: 'm') {
      width: 100%;
    }

    .lead {
      @include margin(null null 20px null);
      @include font('alternative', 'light');
      color: white;
      font-size: rem(23px);
      line-height: 1.52;
    }

    span {
      // MQ
      @include mq($from: 'm') {
        display: block;
      }
    }

    ul {
      display: flex;
      margin-top: 68px;
      color: $color-white;
      font-size: rem(11px);
      line-height: 1;

      // MQ
      @include mq($until: 'm') {
        margin-top: 40px;
      }
    }

    li + li {
      &::before {
        content: '/';
        display: inline-block;
        margin-right: 10px;
        margin-left: 10px;
        vertical-align: middle;
      }
    }

    li:last-child {
      // MQ
      @include mq($until: 's') {
        display: none;
      }
    }

    a {
      color: inherit;
      text-decoration: none;

      .no-touchevents & {
        transition: color 0.6s $ease-out-quart;

        &:hover,
        &:focus {
          color: rgba($color-white, 0.7);
        }
      }
    }
  }

  &-showreel {
    @include font('alternative', 'medium');
    color: $color-white;
    font-size: rem(13px);
    line-height: 1;
    text-decoration: none;

    // MQ
    @include mq($from: 'm') {
      @include position(absolute, 60px null null 50%);
      transform: translateX(-50%);
    }

    @include mq($from: 'xl') {
      margin-left: -60px;
    }

    @include mq($until: 'm') {
      display: block;
      margin-top: 45px;
    }

    .svg {
      fill: $color-red;
      margin-right: 15px;
      margin-bottom: -1px;
    }

    .no-touchevents & {
      .svg {
        transition: transform 0.6s $ease-out-quart;
      }

      &:hover,
      &:focus {
        .svg {
          transform: translateX(6px);
        }
      }
    }
  }
}
