.values-list {
  @include position(relative);

  // Set container in relative position.
  .center {
    @include position(relative);
  }

  .line--1 {
    @include position(absolute, 0 null null 50%);
    @include size(320px, 1px);
    transform: rotate(-45deg) translate(230px, 250px);
  }

  .line--2 {
    @include position(absolute, 990px null null 50%);
    @include size(310px, 1px);
    transform: rotate(45deg) translate(-520px, 520px);
  }

  .line--3 {
    @include position(absolute, null null 200px 50%);
    @include size(330px, 1px);
    transform: rotate(-45deg) translate(175px, 150px);
  }

  .leaves {
    z-index: -1;
    pointer-events: none;
  }

  .leaves--1 {
    @include position(absolute, -45px 10px null null);
  }

  .leaves--2 {
    @include position(absolute, 825px null null -200px);
  }

  .leaves--3 {
    @include position(absolute, -120px -20px null null);
  }

  &-header {
    max-width: 360px;

    .prevent-break {
      white-space: nowrap;
    }
  }

  &-footer {
    max-width: 480px;
  }

  &-header,
  &-footer {
    @include position(relative);

    .values-title {
      font-size: rem(110px);

      // MQ
      @include mq($until: 'xl') {
        font-size: rem(80px);
      }

      @include mq($until: 'l') {
        font-size: rem(55px);
      }

      @include mq($until: 'xxs') {
        font-size: rem(45px);
      }
    }

    .values-subtitle {
      // MQ
      @include mq($from: 'l') {
        margin-left: 7px;
      }
    }

    .values-link {
      @include margin(30px null null);

      // MQ
      @include mq($from: 'l') {
        margin-left: 7px;
      }
    }
  }

  &-header {
    // MQ
    @include mq($from: 'm') {
      @include position(absolute, 1195px 38px null null);
      @include size(310px, auto);
    }

    @include mq($from: 'l') {
      @include position(absolute, 200px 35px null null);
      @include size(auto);
    }

    @include mq($from: 'xl') {
      right: -72px;
    }
  }

  &-footer {
    // MQ
    @include mq($from: 'm') {
      @include position(absolute, null null 5px 35px);
      @include size(310px, auto);
    }

    @include mq($from: 'l') {
      @include position(absolute, null null 280px 45px);
      @include size(auto);
    }

    @include mq($from: 'xl') {
      left: 0;
    }

    @include mq($until: 'm') {
      margin-top: 65px;
    }
  }

  &-row {
    // MQ
    @include mq($from: 'm') {
      display: flex;
      flex-wrap: wrap;
      margin-right: -40px;
      margin-left: -40px;
    }

    + .values-list-row {
      // MQ
      @include mq($from: 'l') {
        margin-top: 85px;
      }
    }

    .values-item {
      // MQ
      @include mq($from: 'm') {
        @include size(50%, auto);
        @include padding(null 40px);
      }

      @include mq($from: 'l') {
        @include size(33.33%, auto);
      }

      @include mq($until: 'l') {
        margin-top: 65px;
      }
    }

    .values-item--4 {
      // MQ
      @include mq($from: 'l') {
        @include margin(255px null 10px);
      }
    }

    .values-item--5 {
      // MQ
      @include mq($from: 'l') {
        @include margin(null null -30px);
      }
    }

    .values-item--10 {
      // MQ
      @include mq($from: 'l') {
        @include margin(430px null null);
      }
    }
  }

  &-row--right {
    // MQ
    @include mq($from: 'l') {
      justify-content: flex-end;
    }
  }

  &-row--center {
    // MQ
    @include mq($from: 'm') {
      justify-content: flex-end;
    }

    @include mq($from: 'l') {
      justify-content: center;
    }

  }
}
