.post-text {
  .center {
    // MQ
    @include mq($from: 'l') {
      display: flex;
    }
  }

  &-column {
    &:nth-child(1) {
      // MQ
      @include mq($from: 'l') {
        flex-direction: column;
      }

      @include mq($from: 'm') {
        display: flex;
        flex-grow: 1;
        justify-content: space-between;
      }
    }

    &:nth-child(2) {
      // MQ
      @include mq($from: 'l') {
        width: 580px;
      }
    }
  }

  &-headline {
    // MQ
    @include mq($from: 'l') {
      @include margin(12px null null);
    }

    @include mq($until: 'l') {
      margin-bottom: 25px;
    }
  }

  &-title {
    @include font('serif', 'medium');
    font-size: rem(30px);
    line-height: (35 / 30);
  }

  &-tagline,
  &-categories {
    @include font('alternative', 'light');
    font-size: rem(18px);
    line-height: (32 / 18);
  }

  &-categories {
    // MQ
    @include mq($until: 'l') {
      display: flex;
      flex-wrap: wrap;
    }

    @include mq($until: 'm') {
      margin-top: 20px;
    }

    @include mq($until: 'l') {
      margin-bottom: 25px;
    }

    li {
      &::after {
        margin-right: 4px;
        
        // MQ
        @include mq($until: 'l') {
          content: ',';
        }
      }

      &:last-child::after {
        // MQ
        @include mq($until: 'l') {
          content: none;
        }
      }
    }
  }

  &-title,
  &-tagline {
    @include margin(null null 30px);
  }

  &-content {
    &.typeset {
      p,
      li,
      ul,
      ol {
        @include font('alternative', 'light');
        font-size: rem(16px);
        line-height: (32 / 16);
      }
    }
  }
}
