[data-theme="case-ginetta"] {
  background-color: #fff;

  &.header-sticky:not(.menu-open) {
    .site-header {
      @include mq($until: 'm') {
        background-color: shade(#1f1a1f, 20%);
      }
    }
  }

  .case-header,
  .case-footer {
    .post-text {
      &-title,
      &-tagline {
        color: #fff;
      }

      &-content {
        p {
          color: rgba(#fff, 0.6);
        }
      }

      &-categories {
        color: #ff0069;
      }
    }

    .post-content {
      &-headline {
        color: #9194a8;

        b {
          color: #ff0069;
        }
      }
    }

    .post-cover {
      background-color: darken(#1f1a1f, 2%);

      img {
        @include object-fit(cover, 50% 50%);
      }
    }
  }

  .case-header {
    background-color: #1f1a1f;

    &-metas {
      color: #ff0069;
    }

    &-back {
      .svg {
        fill: #ff0069;
      }
    }
  }

  .post-contents {
    .post-medias:first-child {
      &::before {
        height: 169px;
        background-color: #1f1a1f;
      }
    }

    .post-content {
      // Mountain Cover
      &:nth-child(6) {
        background-color: #1f1a1f;

        img {
          @include object-fit(cover, 50% 50%);
        }
      }

      // Dark
      &:nth-child(7),
      &:nth-child(8),
      &:nth-child(9),
      &:nth-child(10),
      &:nth-child(11),
      &:nth-child(12),
      &:nth-child(13),
      &:nth-child(14),
      &:nth-child(15),
      &:nth-child(16),
      &:nth-child(17),
      &:nth-child(18),
      &:nth-child(19),
      &:nth-child(20) {
        background-color: #1f1a1f;
      }

      &:nth-child(8),
      &:nth-child(14),
      &:nth-child(16),
      &:nth-child(18) {
        .post-text-title,
        .post-text-tagline {
          color: #fff;
        }

        .post-text-content {
          p {
            color: rgba(#fff, 0.6);
          }
        }
      }

      + .post-content:not(:nth-child(21)) {
        padding-top: 0;
      }
    }
  }

  .post-content {
    &-headline {
      color: #9194a8;

      b {
        color: #ff0069;
      }
    }
  }

  .post-text {
    &-title,
    &-tagline {
      color: #000;
    }

    &-content {
      p {
        color: rgba(#3e3e3e, 0.6);
      }
    }
  }

  .case-next {
    &-headline {
      color: #ff0069;
    }

    &-title {
      color: #000;
    }

    &-link {
      color: #000;
      
      &::after {
        background-color: #ff0069;
      }

      .svg {
        fill: #ff0069;
      }
    }
  }

  .site-footer {
    &-title {
      .baseline {
        fill: #ff0069;
      }
    }

    &-block--social {
      li {
        color: #000;
      }

      a {
        border-color: #ff0069;
      }

      .svg {
        fill: #ff0069;
      }
    }

    &-block--address {
      h3 {
        color: #ff0069;
      }

      p {
        color: rgba(#000, 0.6);
      }
    }

    &-bottom {
      border-color: rgba(#000, 0.3);
    }

    &-contact {
      color: rgba(#000, 0.6);

      a {
        color: #ff0069;
      }

      a::before {
        opacity: 0.5;
        background-color: #9194a8;
      }
    }

    &-newsletter {
      color: #ff0069;

      .svg {
        fill: #ff0069;
      }
    }
  }

  .plyr {
    &--full-ui input[type=range] {
      color: #ff0069;
    }

    &--video {
      .plyr__control:hover,
      .plyr__control.plyr__tab-focus,
      .plyr__control[aria-expanded=true] {
        background: #ff0069;
      }
    }
    
    &--stopped {
      .plyr__poster::before {
        background-color: #1f1a1f;
      }

      .plyr__poster::after {
        border-left-color: #ff0069;
      }
    }
  }
}
