[data-router-view="careers-detail"] {
  @include padding(null null 490px);
  color: $color-blue;

  @include mq($until: 'l') {
    @include padding(null null 40px);
  }

  + .site-footer {
    background-color: transparent;
  }

  .dog-scene {
    display: none;
    z-index: -1;
  }
}

[data-theme="careers-detail"] {
  background-color: color(body-careers);
}
