.site-header {
  @include padding(50px 45px 50px 45px);
  @include position(absolute, 0 null null 0);
  display: flex;
  z-index: 1000;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  transition: transform 1s $ease-out-quad;
  pointer-events: none;

  // MQ
  @include mq($until: 'l') {
    padding-right: 35px;
    padding-left: 35px;
  }

  @include mq($until: 'm') {
    padding-top: 20px;
    padding-bottom: 20px;
    pointer-events: auto;
  }

  &-title {
    display: block;
    width: 84px;
    height: 18px;
    pointer-events: all;
  }

  &-logo {
    display: flex;
    position: relative;
    margin-top: -2px;
    z-index: layer(highest);

    @include mq($until: 's') {
      margin-top: -1px;
    }

    svg {
      flex-shrink: 0;
      width: 104px;
      height: 30px;
      transition: fill .6s $ease-out-quart;
      fill: $color-white;

      @include mq($until: 's') {
        width: 94px;
        height: 27px;
      }

      body.menu-active & {
        transition-delay: 0s;
      }
    }
  }

  &-posts,
  &-cases {
    @include position(absolute, 56px 100px null null);
    @include font('alternative', 'medium');
    display: none;
    color: $color-white;
    font-size: rem(13px);
    line-height: 1;
    text-decoration: none;
    pointer-events: all;
    z-index: layer(highest);
    transition: opacity .6s $ease-out-quad;

    // MQ
    @include mq($until: 'm') {
      @include position(relative, auto auto null null);
      display: inline-block;
    }

    .svg {
      margin-right: 10px;
      margin-bottom: -1px;
      fill: $color-white;
    }

    .no-touchevents & {
      .svg {
        transition: transform 0.6s $ease-out-quart;
      }

      &:hover,
      &:focus {
        .svg {
          transform: translateX(-6px);
        }
      }
    }
  }

  &-posts {
    display: none;

    .single-post & {
      display: block;
    }
  }

  &-cases {
    .single-post & {
      display: none;
    }
  }

  &-button {
    @include position(relative);
    @include size(32px, 30px);
    @include margin(-1px -6px null null);
    @include padding(8px 6px);
    display: block;
    z-index: layer(highest);
    border: 0;
    border-radius: 0;
    background-color: transparent;
    pointer-events: all;
    transition: transform .6s $ease-out-quart;

    .button-bar {
      @include position(absolute, 50% 6px null 6px);
      @include size(auto, 2px);
      @include margin(-1px null null);
      transition: transform .6s $ease-out-quart, opacity .3s $ease-out-quart, background-color .6s $ease-out-quart;
      background-color: white;

      &--1 {
        transform: translateY(-6px);
      }

      &--2 {
        transform-origin: 100% 50%;
        transform: scaleX(0.8);
      }

      &--3 {
        transform: translateY(6px);
      }
    }

    .no-touchevents & {
      &:hover {
        .button-bar--2 {
          transform: scaleX(1);
        }
      }
    }

    &.is-active {
      transform: rotate(-180deg);

      .button-bar {
        transition: transform .6s $ease-out-quart, opacity .3s $ease-out-quart, background-color .6s $ease-out-quart;

        &--1 {
          transform: rotate(45deg);
        }

        &--2 {
          opacity: 0;
        }

        &--3 {
          transform: rotate(-45deg);
        }
      }

      &:not(:focus):hover {
        .button-bar {
          background-color: color(orange);
        }
      }
    }
  }
}

.single-cases {
  .site-header {
    &-cases {
      display: block;
    }
  }
}
.header-sticky {
  .site-header {
    position: fixed;
    top: -129px;
    transform: translateY(-100%);
    transition: transform 1s $ease-out-quart, background-color .6s $ease-out-quart;

    @include mq($until: 'm') {
      top: -69px;
      padding-top: 20px;
      padding-bottom: 20px;
      background-color: shade(color(body), 30%);
    }

    .site-header-logo {
      svg {
        @include mq($until: 'm') {
          // transition: fill .6s $ease-out-quart;
          // fill: $color-blue;
        }
      }
    }

    .button-bar {
      @include mq($until: 'm') {
        // background-color: $color-blue;
      }
    }
  }

  &:not(.header-is-hidden) {
    .site-header {
      transform: translateY(100%);
    }
  }
}

// "Light" theme
[data-theme="careers"],
[data-theme="careers-detail"] {
  &:not(.menu-active) {
    .site-header {
      .button-bar {
        background-color: $color-blue;
      }
    }

    .site-header-logo {
      svg {
        fill: $color-blue;
      }
    }
  }

  &.header-sticky {
    .site-header {
      @include mq($until: 'm') {
        background-color: white;
      }
    }
  }
}

[data-theme="values"] {
  &.header-sticky {
    .site-header {
      @include mq($until: 'm') {
        background-color: shade(color(body-values), 10%);
      }
    }
  }
}

// Setup open menu state
// -----------------------------------------------------------------------------
.menu-active {
  &.header-sticky .site-header {
    @include mq($until: 'm') {
      transition: transform .3s $ease-out-quart, background-color .6s $ease-out-quart;
      background-color: transparent;

      .site-header-logo svg {
        fill: $color-white;
      }

      .button-bar {
        background-color: $color-white;
      }
    }
  }

  .site-header-cases {
    opacity: 0;
    pointer-events: none;
  }

  .site-header-button {
    .button-bar {
      background-color: $color-white;
    }
  }
}
