[data-theme="case-hape"] {
  background-color: #fff;

  &.header-sticky:not(.menu-open) {
    .site-header {
      @include mq($until: 'm') {
        background-color: shade(#80030C, 20%);
      }
    }
  }

  .case-header,
  .case-footer {
    .post-text {
      &-title,
      &-tagline {
        color: #fff;
      }

      &-content {
        p {
          color: rgba(#FFFFFF, 0.6);
        }
      }

      &-categories {
        color: #FFFFFF;
      }
    }

    .post-content {
      &-headline {
        color: rgba(#FFFFFF, 0.5);

        b {
          color: #000000;
        }
      }
    }

    .post-cover {
      background-color: darken(#80030C, 2%);
    }
  }

  .case-header {
    background-color: #80030C;
    padding-bottom: 92px;

    .post-content + .post-content {
      margin-top: 92px;
    }

    &-metas {
      color: #000000;
    }

    &-back {
      .svg {
        fill: #131418;
      }
    }
  }

  .post-contents {
    background-color: #E5E7E7;

    .post-medias:first-child {
      &::before {
        background-color: #80030C;
      }
    }

    .post-content {
      padding-bottom: 92px;
    }

    .post-content + .post-content {
      padding-top: 0;
    }
  }

  .post-content {
    &-headline {
      color: rgba(#000000, 0.5);

      b {
        color: #000000;
      }
    }
  }

  .post-text {
    &-title,
    &-tagline {
      color: #000000;
    }

    &-content {
      p {
        color: #000000;
      }
    }
  }

  .post-medias--list {
    .post-medias-item,
    .post-medias-list-double {
      + .post-medias-item,
      + .post-medias-list-double {
        margin-top: 35px;
      }
    }
  }

  .case-footer {
    .post-quote {
      &-content {
        p {
          color: #FFFFFF;

          &::before {
            color: #000000;
          }
        }

        cite {
          color: rgba(#FFFFFF, 0.45);

          b {
            color: #FFFFFF;
          }
        }
      }
    }

    .post-credits {
      .center {
        border-color: rgba(#ffffff, 0.2);
      }

      dd {
        color: rgba(#FFFFFF, 0.6);
      }

      dt {
        color: rgba(#FFFFFF, 0.45);
      }

      + .post-awards {
        .center {
          border-color: rgba(#FFFFFF, 0.2);
        }
      }
    }

    .post-stats {
      &-label {
        color: rgba(#FFFFFF, 0.5)
      }
    }

    .post-awards {
      margin-top: 65px;

      &-logo {
        background-color: rgba(#FFFFFF, 0.1);
        flex-shrink: 0;
      }

      &-content {
        color: rgba(#FFFFFF, 0.5);

        b {
          color: #FFFFFF;
        }
      }

      .center {
        border-top: solid 1px rgba(#FFFFFF, 0.2);
        padding-top: 65px;
      }
    }

    &-content {
      background-color: #80030C;

      &::before {
        background-color: #80030C;
      }
    }
  }

  .case-next {
    &-headline {
      color: #d79a21;
    }

    &-title {
      color: #060f25;
    }

    &-link {
      color: #000;

      &::after {
        background-color: #d79a21;
      }

      .svg {
        fill: #d79a21;
      }
    }
  }

  .site-footer {
    &-title {
      .baseline {
        fill: #d79a21;
      }
    }

    &-block--social {
      li {
        color: #000;
      }

      a {
        border-color: #d79a21;
      }

      .svg {
        fill: #d79a21;
      }
    }

    &-block--address {
      h3 {
        color: #d79a21;
      }

      p {
        color: rgba(#000, 0.6);
      }
    }

    &-bottom {
      border-color: rgba(#000, 0.3);
    }

    &-contact {
      color: rgba(#000, 0.6);

      a {
        color: #d79a21;
      }

      a::before {
        opacity: 0.5;
        background-color: #9194a8;
      }
    }

    &-newsletter {
      color: #d79a21;

      .svg {
        fill: #d79a21;
      }
    }
  }

  .plyr {
    &--full-ui input[type=range] {
      color: #d79a21;
    }

    &--video {
      .plyr__control:hover,
      .plyr__control.plyr__tab-focus,
      .plyr__control[aria-expanded=true] {
        background: #d79a21;
      }
    }

    &--stopped {
      .plyr__poster::before {
        background-color: #FFFFFF;
      }

      .plyr__poster::after {
        border-left-color: #000000;
      }
    }
  }
}
