.careers-image-slider {
  @include margin(80px null null null);
  counter-reset: caption;
  cursor: move;
  cursor: grab;         /* Support */ // scss-lint:disable VendorPrefix, DuplicateProperty
  cursor: -moz-grab;    /* Support */ // scss-lint:disable VendorPrefix, DuplicateProperty
  cursor: -webkit-grab; /* Support */ // scss-lint:disable VendorPrefix, DuplicateProperty

  @include mq($until: 'm') {
    margin-top: 120px;
  }


  &.is-dragging {
    cursor: grabbing;
    cursor: -moz-grabbing;    /* Support */ // scss-lint:disable VendorPrefix, DuplicateProperty
    cursor: -webkit-grabbing; /* Support */ // scss-lint:disable VendorPrefix, DuplicateProperty
  }

  .image-slider-wrapper {
    @include position(relative);
    display: inline-flex;
    align-items: flex-start;
    justify-content: flex-start;
    width: 100%;

    &.no-pointer {
      // pointer-events: none;
    }
  }

  img {
    @include position(absolute, 0 null null 0);
    @include size(100%, 100%);
    @include object-fit(cover, center);
    display: block;
    transition: transform .5s $ease-out-quad, opacity 1s $ease-out-quad;
    pointer-events: none;

    &.loaded + img {
      opacity: 0;
    }
  }

  figcaption {
    @include position(absolute, 100% null null 0);
    @include padding(16px null null null);
    @include font('alternative', 'regular');
    width: 100%;
    color: #9194a8;
    font-size: rem(12px);
    line-height: rem(19px);

    &::before {
      @include position(absolute, 0 calc(100% + 16px) null null);
      @include padding(null null 6px null);
      @include font('sans-serif', 'bold');
      content: counter(caption, decimal-leading-zero);
      min-width: 30px;
      border-bottom: 1px solid black;
      color: black;
      font-size: rem(8px);
      letter-spacing: ls(400);
      text-align: right;
      counter-increment: caption;
    }
  }

  .line {
    @include position(absolute, 35px -25% null null);
    @include size(330px, 1px);
    z-index: 2;
    transform: rotate(-45deg);
  }

  figure {
    @include position(relative);
    flex-shrink: 0;
    width: 100%;
    user-select: none;

    .image-wrapper {
      @include position(absolute, 0 null null 0);
      @include size(100%, 100%);
      overflow: hidden;
    }

    &:nth-child(5n+1) {
      @include aspect-ratio(515, 324);
      max-width: 515px;
      margin-left: 150px;

      @include mq($until: 'm') {
        max-width: 320px;
      }

      &:nth-child(odd) {
        figcaption {
          @include position(absolute, auto null 100% 0);
          @include padding(null null 16px null);
        }
      }

      &:not(:nth-child(odd)) {
        margin-top: 360px;

        @include mq($until: 'm') {
          margin-top: 0;
        }
      }

      &:not(:first-child) {
        margin-left: 160px;

        @include mq($until: 'm') {
          margin-left: 90px;
        }
      }
    }

    &:nth-child(5n+2) {
      @include aspect-ratio(265, 164);
      max-width: 265px;
      text-align: right;

      figcaption::before {
        right: auto;
        left: calc(100% + 16px);
        text-align: left;
      }

      &:not(:nth-child(odd)) {
        margin-top: 464px;
        margin-right: 265px;
        margin-left: -585px;

        @include mq($until: 'm') {
          margin-top: 290px;
          margin-right: 130px;
          margin-left: -360px;
        }
      }

      &:nth-child(odd) {
        margin-top: 50px;
        margin-right: 60px;
        margin-left: -120px;

        @include mq($until: 'm') {
          margin-top: 300px;
          margin-left: -170px;
        }
      }
    }

    &:nth-child(5n+3) {
      @include aspect-ratio(440, 570);
      max-width: 440px;
      text-align: right;

      @include mq($until: 'm') {
        max-width: 310px;
      }

      figcaption::before {
        right: auto;
        left: calc(100% + 16px);
        text-align: left;
      }

      &:nth-child(odd) {
        margin-top: 200px;

        @include mq($until: 'm') {
          margin-top: 130px;
        }
      }
    }

    &:nth-child(5n+4) {
      @include aspect-ratio(190, 190);
      max-width: 190px;
      margin-left: 108px;

      @include mq($until: 'm') {
        margin-left: 85px;
      }
    }

    &:nth-child(5n+5) {
      @include aspect-ratio(247, 247);
      max-width: 247px;
      margin-top: 272px;
      margin-left: -84px;

      @include mq($until: 'm') {
        max-width: 195px;
      }
    }
  }
}
