.site-cookie {
  @include position(fixed, null null 50px 50px);
  @include padding(40px);
  background-color: $color-blue-g;
  border-radius: 20px;
  z-index: 903;
  width: 100%;
  max-width: 360px;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.3s $ease-out-quad, visibility 0.3s $ease-out-quad;
  
  @include mq($until: 'm') {
    bottom: 0;
    border-radius: 0;
    padding: 45px 30px;
    width: 100%;
    max-width: 100%;
    left: 0;
  }

  &.visible {
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
  }

  &__text {
    color: $text-light;
    font-size: rem(12px);
    line-height: 1.91;

    a {
      color: $text-light;
      transition: color 0.3s $ease-out-quad;

      &:hover {
        color: $white;
      }
    }
  }

  &__buttons {
    display: flex;
    align-items: center;
    margin-top: 20px;
  }

  button {
    @include font('alternative', 'medium');
    font-size: rem(14px);
    line-height: 1;
    flex-shrink: 0;
    border: 0;
    background: transparent;
    padding: 0;
    color: $color-orange;
    transition: color 0.3s $ease-out-quad;

    &:hover {
      color: $white;
    }

    &:first-child {
      margin-left: auto;
      margin-right: 25px;

      @include mq($until: 'm') {
        margin-left: 0;
      }
    }
  }
}