[data-theme="case-tomorrowland"] {
  background-color: #fff;

  &.header-sticky:not(.menu-open) {
    .site-header {
      @include mq($until: 'm') {
        background-color: shade(#060f25, 20%);
      }
    }
  }

  .case-header,
  .case-footer {
    .post-text {
      &-title,
      &-tagline {
        color: #fff;
      }

      &-content {
        p {
          color: rgba(#e4ecff, 0.8);
        }
      }

      &-categories {
        color: #d79a21;
      }
    }

    .post-content {
      &-headline {
        color: rgba(#e4ecff, 0.3);

        b {
          color: #d79a21;
        }
      }
    }

    .post-cover {
      background-color: darken(#060f25, 2%);
    }
  }

  .case-header {
    background-color: #060f25;

    &-metas {
      color: #d79a21;
    }

    &-back {
      .svg {
        fill: #d79a21;
      }
    }
  }

  .post-contents {
    .post-medias:first-child {
      &::before {
        background-color: #060f25;
      }
    }

    .post-content {
      background-color: #fff;

      + .post-content {
        padding-top: 0;
      }
    }
  }

  .post-content {
    &-headline {
      color: #9194a8;

      b {
        color: #d79a21;
      }
    }
  }

  .post-text {
    &-title,
    &-tagline {
      color: #131313;
    }

    &-content {
      p {
        color: rgba(#827392, 0.6);
      }
    }
  }

  .post-medias {
    &-dots {
      button {
        &::before {
          background-color: #827392;
        }

        &::after {
          border-color: rgba(#827392, 0.5);
        }

        .no-touchevents & {
          &:hover,
          &:focus {
            &::before {
              background-color: #d79a21;
            }
          }
        }

        &.is-active {
          &::before {
            background-color: #d79a21;
          }
        }
      }
    }

    &:nth-child(7) {
      .post-medias-list-double {
        &:nth-child(2) {
          @include mq($from: 'm') {
            .post-medias-item {
              &:nth-child(1) {
                width: calc(68.4% - 10px);
              }
  
              &:nth-child(2) {
                width: calc(31.6% - 10px);
              }
            }
          }
        }

        &:nth-child(3) {
          @include mq($from: 'm') {
            .post-medias-item {
              &:nth-child(1) {
                width: calc(52.1% - 10px);
              }
    
              &:nth-child(2) {
                width: calc(47.9% - 10px);
              }
            }
          }
        }
      }
    }
  }

  .case-footer {
    .post-quote {
      &-content {
        p {
          color: #fff;

          &::before {
            color: #d79a21;
          }
        }
  
        cite {
          color: rgba(#e4ecff, 0.3);
  
          b {
            color: #fff;
          }
        }
      }
    }

    .post-stats,
    .post-awards,
    .post-credits {
      .center {
        padding-top: 65px;
        border-top: 1px solid rgba(#fff, 0.2);
      }

      + .post-stats,
      + .post-awards,
      + .post-credits {
        margin-top: 65px;
      }
    }

    .post-credits {
      dd {
        color: rgba(#e4ecff, 0.5);
      }

      dt {
        color: rgba(#e4ecff, 0.3);
      }
    }

    .post-awards {
      &-logo {
        background-color: rgba(#e4ecff, 0.1);
      }

      &-content {
        color: #d79a21;

        b {
          color: #fff;
        }
      }
    }

    .post-stats {
      &-value {
        color: #d79a21;
      }

      &-label {
        color: #fff;
      }
    }

    &-content {
      background-color: #060f25;

      &::before {
        background-color: #060f25;
      }
    }
  }

  .case-next {
    &-headline {
      color: #d79a21;
    }

    &-title {
      color: #060f25;
    }

    &-link {
      color: #060f25;

      &::after {
        background-color: #d79a21;
      }

      .svg {
        fill: #d79a21;
      }
    }
  }

  .site-footer {
    &-title {
      .baseline {
        fill: #d79a21;
      }
    }

    &-block--social {
      li {
        color: #000;
      }

      a {
        border-color: #d79a21;
      }

      .svg {
        fill: #d79a21;
      }
    }

    &-block--address {
      h3 {
        color: #d79a21;
      }

      p {
        color: rgba(#000, 0.6);
      }
    }

    &-bottom {
      border-color: rgba(#000, 0.3);
    }

    &-contact {
      color: rgba(#000, 0.6);

      a {
        color: #d79a21;
      }

      a::before {
        opacity: 0.5;
        background-color: #9194a8;
      }
    }

    &-newsletter {
      color: #d79a21;

      .svg {
        fill: #d79a21;
      }
    }
  }

  .plyr {
    &--full-ui input[type=range] {
      color: #d79a21;
    }

    &--video {
      .plyr__control:hover,
      .plyr__control.plyr__tab-focus,
      .plyr__control[aria-expanded=true] {
        background: #d79a21;
      }
    }
    
    &--stopped {
      .plyr__poster::before {
        background-color: #060f25;
      }

      .plyr__poster::after {
        border-left-color: #d79a21;
      }
    }
  }
}
