.cases-list {
  &-container {
    display: flex;
    flex-wrap: wrap;
    margin-right: -20px;
    margin-bottom: -45px;
    margin-left: -20px;
    transition: opacity 0.6s $ease-out-quart;

    // MQ
    @include mq($until: 'm') {
      margin-right: 0;
      margin-left: 0;
    }

    &.fade-out {
      opacity: 0;
    }

    &.no-inview {
      .cases-item {
        opacity: 1;
        transform: none;
        transition: none;
      }
    }
  }
}

.cases-item {
  @include position(relative);
  @include size(calc(50% - 40px), auto);
  @include margin(null 20px 45px);

  // MQ
  @include mq($until: 's') {
    width: 100%;
    margin-right: 0;
    margin-left: 0;
  }

  &-link {
    @include position(absolute, 0 null null 0);
    @include size(100%);
    z-index: 1;
  }

  &-picture {
    @include position(relative);
    @include size(100%, 575px);
    overflow: hidden;

    // MQ
    @include mq($until: 'l') {
      height: 450px;
    }

    @include mq($until: 's') {
      height: 320px;
    }

    img {
      @include position(absolute, 0 null null 0);
      @include size(100%);
      @include object-fit(cover, 50% 0);
      display: block;
      transition: opacity .6s $ease-out-quad;

      .no-touchevents & {
        transition: transform 1s $ease-out-expo;
      }

      &.js-lazy {
        &.loaded {
          + img {
            opacity: 0;
          }
        }
      }
    }
  }

  &-content {
    @include margin(30px null null);
    text-align: center;
  }

  &-title {
    @include font('serif', 'medium');
    color: $color-white;
    font-size: rem(17px);
    line-height: 1;
  }

  &-text {
    @include margin(10px null null);
    @include font('alternative', 'regular');
    color: $text-light;
    font-size: rem(14px);
    line-height: 1;
  }

  &.is-hidden {
    display: none;
  }

  .no-touchevents & {
    &:hover {
      .cases-item-picture {
        img {
          transform: scale(1.1);
        }
      }
    }
  }
}
