[data-theme="case-jaegerl"] {
  background-color: #fff;

  &.header-sticky:not(.menu-open) {
    .site-header {
      @include mq($until: 'm') {
        background-color: shade(#171d25, 20%);
      }
    }
  }

  .case-header,
  .case-footer {
    .post-text {
      &-title,
      &-tagline {
        color: #fff;
      }

      &-content {
        p {
          color: rgba(#e4ecff, 0.5);
        }
      }

      &-categories {
        color: #b7a98e;
      }
    }

    .post-content {
      &-headline {
        color: rgba(#e4ecff, 0.5);

        b {
          color: #ddbc6f;
        }
      }
    }

    .post-cover {
      background-color: darken(#171d25, 2%);
    }
  }

  .case-header {
    background-color: #171d25;

    &-metas {
      color: #b7a98e;
    }

    &-back {
      .svg {
        fill: #b7a98e;
      }
    }
  }

  .post-contents {
    .post-medias:first-child {
      &::before {
        background-color: #171d25;
      }
    }

    .post-content + .post-content {
      padding-top: 0;
    }
  }

  .post-content {
    &-headline {
      color: #9194a8;

      b {
        color: #b7a98e;
      }
    }
  }

  .post-text {
    &-title,
    &-tagline {
      color: #171d25;
    }

    &-content {
      p {
        color: rgba(#827392, 0.6);
      }
    }
  }

  .case-footer {
    .post-quote {
      &-content {
        p {
          color: #fff;

          &::before {
            color: #d79a21;
          }
        }

        cite {
          color: rgba(#e4ecff, 0.3);

          b {
            color: #fff;
          }
        }
      }
    }

    .post-credits {
      .center {
        border-color: rgba(#ffffff, 0.2);
      }

      dd {
        color: rgba(#e4ecff, 0.5);
      }

      dt {
        color: rgba(#e4ecff, 0.3);
      }

      + .post-awards {
        .center {
          border-color: rgba(#ffffff, 0.2);
        }
      }
    }

    .post-awards {
      &-logo {
        background-color: rgba(#e4ecff, 0.1);
      }

      &-content {
        color: #ddbc6f;

        b {
          color: #fff;
        }
      }
    }

    &-content {
      background-color: #171d25;

      &::before {
        background-color: #171d25;
      }
    }
  }

  .case-next {
    &-headline {
      color: #ddbc6f;
    }

    &-title {
      color: #000;
    }

    &-link {
      color: #000;

      &::after {
        background-color: #ddbc6f;
      }

      .svg {
        fill: #ddbc6f;
      }
    }
  }

  .site-footer {
    &-title {
      .baseline {
        fill: #ddbc6f;
      }
    }

    &-block--social {
      li {
        color: #000;
      }

      a {
        border-color: #ddbc6f;
      }

      .svg {
        fill: #ddbc6f;
      }
    }

    &-block--address {
      h3 {
        color: #ddbc6f;
      }

      p {
        color: rgba(#000, 0.6);
      }
    }

    &-bottom {
      border-color: rgba(#000, 0.3);
    }

    &-contact {
      color: rgba(#000, 0.6);

      a {
        color: #ddbc6f;
      }

      a::before {
        opacity: 0.5;
        background-color: #9194a8;
      }
    }

    &-newsletter {
      color: #ddbc6f;

      .svg {
        fill: #ddbc6f;
      }
    }
  }

  .plyr {
    &--full-ui input[type=range] {
      color: #b7a98e;
    }

    &--video {
      .plyr__control:hover,
      .plyr__control.plyr__tab-focus,
      .plyr__control[aria-expanded=true] {
        background: #171d25;
      }
    }

    &--stopped {
      .plyr__poster::before {
        background-color: #171d25;
      }

      .plyr__poster::after {
        border-left-color: #b7a98e;
      }
    }
  }
}
