.case-footer {
  position: relative;
  z-index: 0;

  &-content {
    @include padding(null null 80px);

    &::before {
      @include position(absolute, -250px null null 0);
      @include size(100%, 250px);
      content: '';
      z-index: -1;
  
      // MQ
      @include mq($until: 'm') {
        top: -139px;
        height: 141px;
      }
    }
  }
}

.case-next {
  margin-top: 130px;

  // MQ
  @include mq($until: 'l') {
    margin-top: 80px;
  }

  &-headline {
    @include margin(null null 35px);
    @include font('sans-serif', 'bold');
    font-size: rem(9px);
    letter-spacing: ls(370px);
    line-height: 1;
    text-transform: uppercase;
  }

  &-title {
    @include font('serif', 'medium');
    font-size: rem(50px);
    line-height: (60 / 50);

    // MQ
    @include mq($until: 'm') {
      font-size: rem(45px);
    }

    @include mq($until: 'xs') {
      font-size: rem(40px);
    }
  }

  &-link {
    @include margin(55px null null);

    &::before {
      background-color: $color-black;
    }
  }
}
