.careers-location {
  @include margin(220px null);

  @include mq($until: 'l') {
    @include margin(90px null);
  }

  &:last-child {
    margin-bottom: 0;
  }

  .center {
    position: relative;
    display: flex;
    align-items: flex-start;
    justify-content: space-between;

    @include mq($until: 'm') {
      display: block;
    }
  }

  .content-wrapper {
    @include padding(10px null null null);
    @include margin(null 130px null null);
    max-width: 300px;

    @include mq($until: 'xl') {
      margin-right: 0;
    }

    @include mq($until: 'm') {
      padding-top: 30px;
    }
  }

  figure {
    max-width: 494px;
    overflow: hidden;

    @include mq($until: 'xl') {
      max-width: 50%;
    }

    @include mq($until: 'm') {
      max-width: 100%;
    }

    img {
      display: block;
      width: 100%;
      transition: transform .6s $ease-out-quad;
    }
  }

  .headline {
    @include margin(null null 30px null);
    @include font('serif', 'regular');
    display: block;
    color: #9194a8;
    font-size: rem(14px);
    line-height: 1;
  }

  &-title {
    @include font('serif', 'medium');
    @include margin(null null 40px null);
    color: $color-blue;
    font-size: rem(80px);
    line-height: 1;

    @include mq($until: 'xl') {
      font-size: rem(56px);
    }

    @include mq($until: 'm') {
      font-size: rem(48px);
    }
  }

  p {
    color: rgba($color-blue, .8);
    line-height: 1.78;
  }

  .location-positions-label {
    @include font('alternative', 'bold');
    @include margin(45px null 20px null);
    display: block;
    color: $color-red;
    font-size: rem(9);
    letter-spacing: 4px;
    line-height: 1;
    text-transform: uppercase;
  }

  h3 {
    @include font('alternative', 'light');
    color: $color-black;
    font-size: rem(26px);
    letter-spacing: ls(-40);
    line-height: 1.16;

    @include mq($until: 'xl') {
      font-size: rem(24px);
    }

    .no-touchevents & {
      transition: color 0.6s $ease-out-quart;
    }
  }

  ul {
    a {
      @include position(relative);
      @include padding(16px null);
      display: block;
      text-decoration: none;

      .no-touchevents & {
        &:hover,
        &:focus {
          h3 {
            color: $color-red;
          }
        }
      }
    }

    li + li a::before {
      @include position(absolute, 0 null null 0);
      @include size(100%, 1px);
      content: '';
      background-image: image('decorations/dots.png');
      background-size: 12px 1px;
    }
  }

  &.is-reversed {
    .center {
      flex-direction: row-reverse;
    }

    .content-wrapper {
      @include margin(null 0 null null);
    }

    figure {
      @include mq($from: 'xl') {
        max-width: 530px;
      }
    }
  }
}
