.post-opensea {
  position: relative;

  &-wrapper {
    @include aspect-ratio(1, 1);
    @include size(100%, auto);
    max-width: 600px;
    margin: 0 auto;
    border-radius: 20px;
    border: 1px solid #dadada;
    overflow-x: hidden;
    overflow-y: hidden;
    background-color: #fff;
  }

  &-inner {
    @include position(absolute, 0 null null 0);
    @include size(100%);
    display: flex;
    flex-direction: column;
  }

  &-header {
    padding: 13px 16px 8px;

    a {
      display: inline-block;
    }

    img {
      display: block;
      width: 121px;
      height: auto;
    }
  }

  iframe {
    display: block;
    flex: 1;
    width: 100%;
    border: none;
  }
}
