.archive-filters {
  @include position(absolute, 57px calc((100vw - 1024px) * 0.5) null null);

  // MQ
  @include mq($until: 1200px) {
    display: none;
  }

  &-list {
    display: flex;
    align-items: flex-start;
    margin-right: -15px;
    margin-left: -15px;
  }

  &-item {
    @include padding(null 15px);
    @include font('sans-serif', 'regular');
    color: $color-blue-f;
    font-size: rem(10px);
    letter-spacing: ls(360);
    line-height: 1;
    text-transform: uppercase;

    // Border
    + .archive-filters-item {
      border-left: 1px solid rgba($color-blue-f, .25);
    }

    // Adjust space aroung of first item
    &:nth-child(1) {
      margin-top: 1px;
      padding-right: 20px;
      padding-left: 0;
    }

    // Remove border on second item
    &:nth-child(2) {
      border-left: 0 none;
    }
  }

  &-button {
    @include position(relative);
    @include margin(0);
    @include padding(0);
    @include font('sans-serif', 'bold');
    border: 0 none;
    background: none;
    color: $color-white;
    font-size: rem(13px);
    letter-spacing: 0;
    line-height: 1;
    text-transform: none;
    cursor: pointer;

    &::after {
      @include position(absolute, null null -10px 0);
      @include size(100%, 1px);
      content: '';
      transform: scale(0, 1);
      transform-origin: 100% 50%;
      background-color: $color-red;

      .no-touchevents & {
        transition: transform 0.4s $ease-out-quart;
      }
    }

    .no-touchevents & {
      &:hover {
        &::after {
          transform: scale(1);
          transform-origin: 0% 50%;
        }
      }
    }

    &.is-active {
      &::after {
        transform: scale(1);
        transform-origin: 0% 50%;
      }
    }
  }
}
